def fill_labels(iteration, f_name):
   a = np.zeros((434,646,251))
   b = np.zeros((434,646,251))
   c = np.zeros((434,646,251))
   d = np.zeros((434,646,251))

   f = open(f_name, 'r')
   for line in f.readlines():
      fields = line.split(' ')
      a[int(fields[0])][int(fields[1])][int(fields[2])]=float(fields[3])
   f.close()

   return a, b, c, d


